function _stop() {
  if (!_nodes) return;
  const AC = audio.boot();
  const { oscs, g } = _nodes;
  g.gain.setTargetAtTime(0, AC.currentTime, 0.05);
  oscs.forEach(o => { try { o.stop(AC.currentTime + 0.2); } catch (e) {} });
  _nodes = null;
  _params.active = false;
  sBus.publish('org:state_sync', { active: false });
}
